"""
Workspace / filesystem endpoints under `/api/files/*`.

Covers uploads, directory listing, text & binary content reads, and
directory creation. When `scaffold:true` is passed to mkdir, the project is
built using the canonical xo-projects layout (see
``services.cowork_agent.project_layout``). All paths are clamped to the
user's home dir for safety.
"""

import base64
import hashlib
import mimetypes
import shutil
from pathlib import Path

from fastapi import APIRouter, File, Form, HTTPException, Request, UploadFile
from fastapi.responses import FileResponse, JSONResponse

from services.cowork_agent.project_layout import (
    project_dir,
    scaffold_project,
    xo_projects_root,
)

router = APIRouter()

_MAX_UPLOAD_BYTES = 100 * 1024 * 1024  # 100 MB
_MAX_PAGE_LIMIT = 500
_DEFAULT_LIMIT = 50


# ── Cursor helpers ────────────────────────────────────────────────────────────


def _encode_cursor(offset: int) -> str:
    return base64.b64encode(str(offset).encode()).decode()


def _decode_cursor(cursor: str) -> int:
    try:
        return int(base64.b64decode(cursor.encode()).decode())
    except Exception:
        raise ValueError("Invalid cursor")


# ── Routes ───────────────────────────────────────────────────────────────────


@router.post("/api/files/upload")
async def upload_file(
    file: UploadFile = File(...),
    workspace: str = Form(""),
):
    """Save an uploaded file into the workspace (or ~/uploads fallback)."""
    content = await file.read(_MAX_UPLOAD_BYTES + 1)
    if len(content) > _MAX_UPLOAD_BYTES:
        raise HTTPException(status_code=413, detail="File exceeds 100 MB limit")
    content_hash = hashlib.sha256(content).hexdigest()

    if workspace:
        dest_dir = Path(workspace).resolve()
    else:
        dest_dir = Path.home() / "uploads"
    dest_dir.mkdir(parents=True, exist_ok=True)

    filename = file.filename or "upload"
    dest = dest_dir / filename

    # Avoid overwriting -- append hash suffix if name collides with different content
    if dest.exists():
        existing_hash = hashlib.sha256(dest.read_bytes()).hexdigest()
        if existing_hash != content_hash:
            stem = dest.stem
            suffix = dest.suffix
            dest = dest_dir / f"{stem}_{content_hash[:8]}{suffix}"

    dest.write_bytes(content)

    mime = file.content_type or mimetypes.guess_type(filename)[0] or "application/octet-stream"

    return {
        "file_id": content_hash[:16],
        "name": dest.name,
        "path": str(dest),
        "size": len(content),
        "mime_type": mime,
        "source": "uploaded",
        "content_hash": content_hash,
    }


@router.post("/api/files/list-directory")
async def list_directory(request: Request):
    """List files and directories at a given path, with optional cursor-based pagination.

    Body fields:
    - ``path`` (str, optional): directory to list; defaults to home.
    - ``limit`` (int, optional): max entries to return per page (default 50, max 500).
    - ``cursor`` (str, optional): opaque pagination token returned by a previous call.

    Response includes ``next_cursor`` (null when no more results).
    Existing clients that omit ``limit`` and ``cursor`` continue to work unchanged.
    """
    body = await request.json()
    raw_path = body.get("path")
    base = Path.home()

    if raw_path:
        target = Path(raw_path).resolve()
        # Prevent traversal outside home
        if not str(target).startswith(str(base)):
            return JSONResponse(status_code=403, content={"detail": "Access denied"})
    else:
        target = base

    if not target.is_dir():
        return JSONResponse(status_code=404, content={"detail": "Not a directory"})

    raw_limit = body.get("limit", _DEFAULT_LIMIT)
    try:
        limit = max(1, min(int(raw_limit), _MAX_PAGE_LIMIT))
    except (TypeError, ValueError):
        limit = _DEFAULT_LIMIT

    raw_cursor = body.get("cursor")
    if raw_cursor:
        try:
            offset = _decode_cursor(raw_cursor)
        except ValueError:
            return JSONResponse(status_code=400, content={"detail": "Invalid cursor"})
    else:
        offset = 0

    all_entries = []
    try:
        for entry in sorted(target.iterdir(), key=lambda e: (not e.is_dir(), e.name.lower())):
            if entry.is_dir():
                all_entries.append({"name": entry.name, "path": str(entry), "type": "dir"})
            else:
                all_entries.append({"name": entry.name, "path": str(entry), "type": "file"})
    except PermissionError:
        pass

    page = all_entries[offset : offset + limit]
    next_offset = offset + limit
    next_cursor = _encode_cursor(next_offset) if next_offset < len(all_entries) else None

    dirs = [{"name": e["name"], "path": e["path"]} for e in page if e["type"] == "dir"]
    files = [{"name": e["name"], "path": e["path"]} for e in page if e["type"] == "file"]

    parent = str(target.parent) if target != base else None

    return {
        "path": str(target),
        "parent": parent,
        "dirs": dirs,
        "files": files,
        "next_cursor": next_cursor,
    }


